@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap");
@import "tailwindcss";
@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

/* One token set: light-dark() picks the value from color-scheme, which data-theme sets below.
   "system" follows the OS in CSS, so there is no light flash before ThemePreference runs. */
@theme {
  --font-sans: "Inter", Arial, sans-serif;
  --font-mono: "JetBrains Mono", Consolas, monospace;
  --radius-lg: 0.625rem;
  --color-background: light-dark(#f6f7f9, #0e0f12);
  --color-card: light-dark(#ffffff, #16181d);
  --color-foreground: light-dark(#16181d, #e7e9ee);
  --color-muted: light-dark(#eff1f4, #1f2228);
  --color-muted-foreground: light-dark(#5b6270, #9ca3af);
  --color-border: light-dark(#e2e5ea, #2b2f37);
  --color-primary: light-dark(#16181d, #e7e9ee);
  --color-primary-foreground: light-dark(#ffffff, #16181d);
  --color-accent: light-dark(#eaecf1, #252830);
  --color-accent-foreground: light-dark(#16181d, #e7e9ee);
  --color-brand: light-dark(#4353d6, #8e9cff);
  --color-sidebar: light-dark(#fbfbfc, #121317);
  --color-success: light-dark(#067647, #4ade80);
  --color-success-soft: light-dark(#ecfdf3, #0f2a1c);
  --color-warning: light-dark(#a74b06, #fbbf24);
  --color-warning-soft: light-dark(#fffaeb, #2b2108);
  --color-danger: light-dark(#b42318, #f87171);
  --color-danger-soft: light-dark(#fef3f2, #2e1414);

  /* Status shades pages already use follow the theme instead of a fixed palette. */
  --color-red-700: var(--color-danger);
  --color-red-800: var(--color-danger);
  --color-red-50: var(--color-danger-soft);
  --color-amber-700: var(--color-warning);
  --color-amber-50: var(--color-warning-soft);
  --color-emerald-700: var(--color-success);
  --color-emerald-50: var(--color-success-soft);
  --color-blue-700: var(--color-brand);
  --color-blue-50: var(--color-accent);
  --color-slate-100: var(--color-muted);
  --color-slate-600: var(--color-muted-foreground);
  --color-slate-700: var(--color-foreground);
}

:root { color-scheme: light dark; }
:root[data-theme="light"] { color-scheme: light; }
:root[data-theme="dark"] { color-scheme: dark; }

body {
  font-feature-settings: "cv11", "ss01";
}

:focus-visible {
  outline: 2px solid var(--color-brand);
  outline-offset: 2px;
}

fieldset { min-width: 0; }
main { overflow-wrap: anywhere; }
main select { min-width: 0; max-width: 100%; }

html[data-theme="dark"] .bg-brand.text-white { color: var(--color-primary-foreground); }

.ai-markdown { min-width: 0; max-width: 100%; overflow-wrap: anywhere; font-size: 15px; line-height: 1.75; }
.ai-markdown > :first-child { margin-top: 0; }
.ai-markdown p { margin-block: 12px; white-space: pre-wrap; }
.ai-markdown h1,.ai-markdown h2,.ai-markdown h3 { font-size: 18px; font-weight: 600; line-height: 1.4; margin-block: 24px 10px; letter-spacing: -.4px; }
.ai-markdown h4,.ai-markdown h5,.ai-markdown h6 { font-weight: 600; margin-block: 12px 6px; }
.ai-markdown ul,.ai-markdown ol { padding-left: 22px; margin-block: 12px; }
.ai-markdown ul { list-style: disc; }.ai-markdown ol { list-style: decimal; }
.ai-markdown a { color: var(--color-brand); text-decoration: underline; text-underline-offset: 3px; }
.ai-markdown blockquote { margin-block: 16px; border-left: 3px solid var(--color-brand); background: var(--color-accent); padding: 8px 16px; }
.ai-markdown hr { border-color: var(--color-border); margin-block: 18px; }
.ai-markdown :not(pre) > code { font: 12px var(--font-mono); background: var(--color-muted); padding: 2px 5px; border-radius: 4px; }
.ai-code { border: 1px solid var(--color-border); border-radius: 8px; overflow: hidden; margin-block: 16px; }
.ai-code-header { display: flex; justify-content: space-between; gap: 12px; padding: 8px 12px; background: var(--color-muted); color: var(--color-muted-foreground); font: 10px/1.6 var(--font-mono); }
.ai-code-header button { color: var(--color-brand); cursor: pointer; }
.ai-code pre { background: #101b29; color: #d7e7fc; padding: 16px; overflow-x: auto; font: 12px/1.75 var(--font-mono); }
.ai-table { overflow-x: auto; margin-block: 16px; }
.ai-table table { width: 100%; border-collapse: collapse; font-size: 12px; }
.ai-table td,.ai-table th { padding: 9px; border-bottom: 1px solid var(--color-border); text-align: left; }
.ai-table th { color: var(--color-muted-foreground); background: var(--color-muted); font-weight: 500; }
.ai-table td:last-child,.ai-table th:last-child { text-align: right; font-variant-numeric: tabular-nums; }

